from pathlib import Path
import csv

INPUT_FILE = Path('/app/data/transactions.dat')
OUTPUT_FILE = Path('/app/output/transactions.csv')
RECORD_SIZE = 41
TEXT_ENCODING = 'cp500'

TYPE_MAP = {'C': 'CREDIT', 'D': 'DEBIT'}
STATUS_MAP = {'A': 'ACTIVE', 'P': 'PENDING', 'E': 'ERROR'}


def decode_text(raw):
    return raw.decode(TEXT_ENCODING)


def unpack_comp3(raw):
    nibbles = []
    for byte in raw:
        nibbles.append(byte >> 4)
        nibbles.append(byte & 0x0F)
    digits = nibbles[:-1]
    sign = nibbles[-1]
    if any(d > 9 for d in digits):
        raise ValueError('invalid COMP-3 digit nibble in ' + raw.hex())
    value = 0
    for digit in digits:
        value = value * 10 + digit
    if sign == 0x0D:
        value = -value
    elif sign not in (0x0C, 0x0F):
        raise ValueError('invalid COMP-3 sign nibble in ' + raw.hex())
    return value


def format_cents(cents):
    sign = '-' if cents < 0 else ''
    dollars, remainder = divmod(abs(cents), 100)
    return sign + str(dollars) + '.' + str(remainder).zfill(2)


def main():
    data = INPUT_FILE.read_bytes()
    if len(data) % RECORD_SIZE != 0:
        raise ValueError('input size is not a multiple of the record size')
    OUTPUT_FILE.parent.mkdir(parents=True, exist_ok=True)
    with OUTPUT_FILE.open('w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['account_id', 'trans_type', 'amount', 'description', 'status'])
        for offset in range(0, len(data), RECORD_SIZE):
            record = data[offset:offset + RECORD_SIZE]
            account_id = decode_text(record[1:9])
            trans_type = TYPE_MAP[decode_text(record[9:10])]
            amount = format_cents(unpack_comp3(record[10:15]))
            description = decode_text(record[15:40]).rstrip()
            status = STATUS_MAP[decode_text(record[40:41])]
            writer.writerow([account_id, trans_type, amount, description, status])


if __name__ == '__main__':
    main()
